mapper.select:
SELECT a.approval_id AS approvalId, a.operation_id AS operationId, a.state AS state, a.requirement AS requirement, a.argument_digest AS argumentDigest, a.target_resource AS targetResource, a.approver_scope AS approverScope, a.approver_id AS approverId, a.expires_at AS expiresAt, a.decided_at AS decidedAt, a.created_at AS createdAt, o.run_id AS runId, a.tenant_id AS tenantId FROM approval a JOIN tool_operation o ON o.tenant_id = a.tenant_id AND o.operation_id = a.operation_id WHERE a.tenant_id = #{tenantId}::uuid AND a.state = #{state}::approval_state
AND a.approval_id < #{cursorApprovalId}::uuid
ORDER BY a.created_at DESC, a.approval_id DESC LIMIT #{limit}
